class Solution {
public:
    int longestArithSeqLength(vector<int>& nums) {
        int n = nums.size();
        int max_len = 2;
        vector<vector<int>> dp(n, vector<int>(1001, 1));
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < i; ++j) {
                int diff = nums[i] - nums[j] + 500;
                dp[i][diff] = max(dp[i][diff], dp[j][diff] + 1);
                max_len = max(max_len, dp[i][diff]);
            }
        }
        return max_len;
    }
};

class Solution {
    public int longestArithSeqLength(int[] nums) {
        int n = nums.length;
        int maxLen = 2;
        int[][] dp = new int[n][1001];
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < i; ++j) {
                int diff = nums[i] - nums[j] + 500;
                dp[i][diff] = Math.max(dp[i][diff], (dp[j][diff] == 0 ? 1 : dp[j][diff]) + 1);
                maxLen = Math.max(maxLen, dp[i][diff]);
            }
        }
        return maxLen;
    }
}

var longestArithSeqLength = function(nums) {
    const n = nums.length;
    let maxLen = 2;
    const dp = new Array(n).fill(null).map(() => new Map());
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            const diff = nums[i] - nums[j];
            const prev = dp[j].get(diff) || 1;
            const cur = prev + 1;
            dp[i].set(diff, Math.max(dp[i].get(diff) || 0, cur));
            if (cur > maxLen) maxLen = cur;
        }
    }
    return maxLen;
};
